import{state}from"./state.js";import{renderShop,renderRequests}from"./ui.js";import{showToast,showConfirm,showMobileEventNotification,escapeHtml}from"./utils.js";import{scheduleSave,addHistoryEntry,checkDailyCoinLimit,getActingChildId,updateBalanceLocally,addRequestEntry,checkFrequency}from"./action-helpers.js";import{triggerTaskAnimation}from"./motion-feedback.js";export function earnCoins(e){const t=state.tasks.find(t=>t.id==e);if(!t)return;const i="admin"===state.role?state.currentChildId:state.children[0]?.id||null;if(!i){const e=state.isAdmin&&0===state.children.length?"Сначала добавьте ребенка":"Сначала выберите ребенка";return showToast(e,"error")}const n=[checkFrequency(t,i),checkDailyCoinLimit(i,t.coins)].filter(Boolean),o=()=>{updateBalanceLocally(i,t.coins),addHistoryEntry({type:"earn",amount:t.coins,description:t.name,groupName:t.groupName,comment:t.comment,relatedId:t.id,childIdOverride:i}),renderShop(),showMobileEventNotification(`+${t.coins} мон. начислено!`,"success","Balance updated"),triggerTaskAnimation()};if(n.length>0)return showConfirm("Превышен лимит",`${n.join(". ")}. Все равно начислить?`,{onConfirm:o});const s=`Подтвердить выполнение задания "${escapeHtml(t.name)}" за ${t.coins} <span class="gamified-icon icon-coin-stack" aria-hidden="true" style="width: 1.2rem; height: 1.2rem; vertical-align: middle;"></span>?`;showConfirm("Выполнить задание?",s,{onConfirm:o})}export function requestCoins(e){const t=state.tasks.find(t=>t.id==e);if(!t)return;const i=getActingChildId();if(!i)return showToast("Сначала выберите ребенка","error");const n=[checkFrequency(t,i),checkDailyCoinLimit(i,t.coins)].filter(Boolean);if(n.length>0)return showConfirm("Лимит исчерпан",n.join(". "),{cancelLabel:"Понятно",hideConfirm:!0});const o=`"${escapeHtml(t.name)}" за ${t.coins} <span class="gamified-icon icon-coin-stack" aria-hidden="true" style="width: 1.2rem; height: 1.2rem; vertical-align: middle;"></span>`;showConfirm("Отправить заявку?",o,{onConfirm:()=>{addRequestEntry({childId:i,requestType:"earn",taskId:t.id,taskName:t.name,coins:t.coins,taskGroup:t.groupName,taskComment:t.comment}),scheduleSave(),renderRequests(),document.querySelector('.nav__btn[data-tab="requests"]')?.click(),showMobileEventNotification("Заявка отправлена!","success","Новая заявка"),triggerTaskAnimation()}})}